import React, { useState } from "react";
import MapView from "./components/MapView";
import ListView from "./components/ListView";
import events from "./data/events";
import "./index.css";

const NAV_ITEMS = [
	{ id: "map", label: "CARTE" },
	{ id: "list", label: "ÉVÉNEMENTS" },
	{ id: "about", label: "À PROPOS" },
];

function About() {
	return (
		<div style={{ maxWidth: 640, margin: "64px auto", padding: "0 24px" }}>
			<h1 style={{ fontSize: 56, marginBottom: 24, lineHeight: 1 }}>
				Mujawara : tisser un voisinage révolutionnaire par-delà les
				frontières
			</h1>
			<p
				style={{
					fontSize: 15,
					lineHeight: 1.8,
					color: "var(--text-secondary)",
					fontWeight: 300,
				}}
			>
				Mujawara — du mot arabe <em>مجاورة</em>, "voisinage" — est une
				cartographie des événements politiques et militants à travers le
				monde. Un outil pour connecter les luttes, visualiser les
				résistances, tisser l'internationalisme.
			</p>
		</div>
	);
}

export default function App() {
	const [view, setView] = useState("map");

	return (
		<div
			style={{
				minHeight: "100vh",
				display: "flex",
				flexDirection: "column",
			}}
		>
			<header
				style={{
					height: 60,
					background: "var(--surface)",
					borderBottom: "1px solid var(--border)",
					display: "flex",
					alignItems: "center",
					padding: "0 32px",
					position: "sticky",
					top: 0,
					zIndex: 1000,
				}}
			>
				{/* Logo */}
				<button
					onClick={() => setView("map")}
					style={{
						background: "none",
						border: "none",
						cursor: "pointer",
						padding: 0,
						fontFamily: "var(--font-title)",
						fontWeight: 800,
						fontStyle: "italic",
						fontSize: 30,
						color: "var(--text-primary)",
						letterSpacing: "-0.5px",
						lineHeight: 1,
					}}
				>
					MUJAWARA
				</button>

				{/* Nav — centrée absolument */}
				<nav
					style={{
						position: "absolute",
						left: "50%",
						transform: "translateX(-50%)",
						display: "flex",
						gap: 4,
					}}
				>
					{NAV_ITEMS.map(({ id, label }) => (
						<button
							key={id}
							onClick={() => setView(id)}
							style={{
								background: "none",
								border: "none",
								borderBottom:
									view === id
										? "2px solid var(--text-primary)"
										: "2px solid transparent",
								borderRadius: 0,
								cursor: "pointer",
								fontFamily: "var(--font-title)",
								fontStyle: "italic",
								fontWeight: 600,
								fontSize: 18,
								color:
									view === id
										? "var(--text-primary)"
										: "var(--text-muted)",
								padding: "6px 14px",
								transition: "all 0.15s",
								letterSpacing: "-0.3px",
							}}
						>
							{label}
						</button>
					))}
				</nav>
			</header>

			<main style={{ flex: 1 }}>
				{view === "map" && <MapView events={events} />}
				{view === "list" && <ListView events={events} />}
				{view === "about" && <About />}
			</main>
		</div>
	);
}
